/// `GetEnvObjectTypeFromHelperName @001e1dec`: exact (case-insensitive) match first, else the first entry whose name partially matches.
/// When several entries share a name the original picks one at random; this returns the first (UNRESOLVED: random choice, only
/// `smck_blocker_snow_a` is duplicated and both entries share smackable type 0x6b).
pub fn env_object_for_helper(name: &str) -> Option<usize> {
    if let Some(i) = ENV_OBJECTS.iter().position(|e| e.name.eq_ignore_ascii_case(name)) {
        return Some(i);
    }
    ENV_OBJECTS.iter().position(|e| partial_match_nocase(name, e.name))
}

/// `StringPartialMatchNoCase @002c0474`: true when `prefix` (the second argument) is a case-insensitive prefix of `s`
/// (the loop ends with "match" as soon as the second string hits its NUL).
pub fn partial_match_nocase(s: &str, prefix: &str) -> bool {
    s.len() >= prefix.len() && s.as_bytes()[..prefix.len()].eq_ignore_ascii_case(prefix.as_bytes())
}
